/* HEXA BATTLEGROUNDS upgrade — PART 16 OF 31. Only for databases that already ran setup part-01…; Run in order. Safe to re-run. */ create or replace function host_command(p_token text, p_arena uuid, p_cmd text, p_args jsonb default '{}'::jsonb, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_ids uuid[]; v_id uuid; v_out jsonb := '{}'::jsonb; v_err text; v_res jsonb; v_delta interval; v_logargs jsonb; v_all_ok text[] := array['open_boarding','assign_buses','drive','finalize_roles','pause','resume','broadcast','clear_overlay', 'blackout','countdown','story','bargain','zone_warn','zone_now','zone_cancel','zone_set','spawn_airdrop','begin_finale', 'finale_stage','launch_sync','close_sync','lock_results','reveal_winner','end_game','reveal_squad00', 'next_phase','set_phase','hide_rankings','red_zone','red_cancel']; v_new text[] := array['set_phase','next_phase','hide_rankings','reset_pin','red_zone','red_cancel']; begin v_ev := _auth_host(p_token); p_args := coalesce(p_args, '{}'::jsonb); v_logargs := p_args - 'pin'; if p_arena is null then if p_cmd = any(v_all_ok) then select array_agg(id order by number) into v_ids from arenas where event_id = v_ev; else v_ids := array[null::uuid]; end if; else if not exists (select 1 from arenas where id = p_arena and event_id = v_ev) then raise exception 'BAD_ARENA'; end if; v_ids := array[p_arena]; end if; foreach v_id in array v_ids loop begin v_delta := null; if p_cmd = 'resume' then select now() - paused_at into v_delta from arenas where id = v_id and paused; end if; if p_cmd in ('open_boarding', 'assign_buses', 'drive') and v_id is not null and not exists (select 1 from teams where arena_id = v_id and ready) then raise exception 'NO_READY_SQUADS'; end if; if p_cmd = any(v_new) then v_res := _host_exec_p0(v_ev, v_id, p_cmd, p_args, p_reason); elsif p_cmd = 'clear_overlay' then update arenas set overlay = (select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) from jsonb_each(overlay) as x(k, v) where k in ('match', 'zone', 'world', 'red')) where id = v_id; v_res := '{}'::jsonb; else v_res := _host_exec(v_ev, v_id, p_cmd, p_args, p_reason); end if; if p_cmd = 'resume' and v_delta is not null then update arenas set phase_next_at = phase_next_at + v_delta, phase_started_at = phase_started_at + v_delta, shuttle_departed_at = shuttle_departed_at + v_delta, overlay = case when overlay ? 'match' and overlay #>> '{match,next_at}' is not null then jsonb_set(overlay, '{match,next_at}', to_jsonb((overlay #>> '{match,next_at}')::timestamptz + v_delta)) else overlay end where id = v_id; elsif p_cmd = 'begin_finale' then update arenas set match_phase = 5, phase_started_at = now(), phase_next_at = null, overlay = overlay || jsonb_build_object('match', jsonb_build_object('phase', 5, 'started_at', now(), 'next_at', null, 'zone_target', 5)) where id = v_id; perform _feed(v_id, 'phase.started', jsonb_build_object('phase', 5)); elsif p_cmd = 'zone_cancel' then update arenas set zone_hold = true where id = v_id; elsif p_cmd in ('zone_warn', 'zone_now', 'zone_set') then update arenas set zone_hold = false where id = v_id; elsif p_cmd = 'reset_arena' then update arenas set match_phase = 0, phase_started_at = null, phase_next_at = null, zone_hold = false, red_x = null, red_y = null, red_r = null, red_at = null, last_red_at = null where id = v_id; update teams set zone_hit_at = null, travel_fx = null, travel_fy = null where arena_id = v_id; end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), v_res); insert into audit_log(event_id, arena_id, actor, action, args, reason) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason); exception when others then v_err := sqlerrm; insert into audit_log(event_id, arena_id, actor, action, args, reason, ok, error) values (v_ev, v_id, 'host', p_cmd, v_logargs, p_reason, false, v_err); if array_length(v_ids, 1) = 1 then return jsonb_build_object('ok', false, 'error', v_err); end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), jsonb_build_object('error', v_err)); end; if v_id is not null then perform _zone_publish(v_id); perform _ping_arena(v_id, 'host'); end if; end loop; return jsonb_build_object('ok', true, 'result', v_out); end $$; drop function if exists host_create_trial(text, text, text, int); drop function if exists host_trial_status(text); update arenas set overlay = overlay - 'trial' where overlay ? 'trial'; do $$ declare r record; begin for r in select id from arenas loop perform _zone_publish(r.id); end loop; end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; alter table mission_instances add column if not exists revealed jsonb not null default '{}'::jsonb; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 0, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6, 'move_speed', 25, 'loc_radius', 35, 'engage_range', 60, 'zone_tick_seconds', 6, 'zone_tick_damage', 4, 'red_interval', 0, 'red_warning', 20, 'red_damage', 30, 'red_radius', 80 ) || jsonb_build_object( 'reveal_pct', 50 ) $$;
